-- 新增「幻象*」系列变身物品（模板：68011 幻象*恶魔形态）
--
-- 说明：
-- 1. 物品由 PlayerTransmog_ItemScript 使用：读取 description（= 生物 DisplayID）作为变身模型，
--    并按 Quality 归入对应品质分组，因此 description 必须填模型的 DisplayID。
-- 2. entry 从 68012 起顺延，共 32 件，68012 ~ 68043。
-- 3. 对照表中标注 "+" 的新增模型本批不产出物品，故 DisplayID 不连续。
-- 4. 仅写入与 item_template 列默认值不同的字段，其余列走数据库默认值。

DELETE FROM `item_template` WHERE `entry` BETWEEN 68012 AND 68043;

